import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.k9nOhppk.js";const y=JSON.parse('{"title":"Benchmarks against Go","description":"","frontmatter":{"title":"Benchmarks against Go"},"headers":[],"relativePath":"internals/benchmarks.md","filePath":"internals/benchmarks.md","lastUpdated":1791864160000}'),r={name:"internals/benchmarks.md"};function n(d,t,l,h,o,g){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="benchmarks-against-go" tabindex="-1">Benchmarks against Go <a class="header-anchor" href="#benchmarks-against-go" aria-label="Permalink to &quot;Benchmarks against Go&quot;">​</a></h1><p>The bar for natively compiled Eyelang is <strong>faster than Go, on less memory</strong>, with Go as the baseline. Each benchmark in <a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench" target="_blank" rel="noreferrer"><code>testdata/bench</code></a> is an Eyelang program and the same algorithm written as idiomatic Go. The Eyelang program is compiled with <code>eye build</code> (C at <code>-O2</code>, through the pinned zig) and the Go one with <code>go build</code>; both print the same result, which the tool checks. The interpreter (<code>eye run --memory</code>) runs the same program for comparison.</p><p>Native code and Go ran 5 times each, taking turns, and the interpreter 1 time. Times are the fastest run&#39;s wall clock, start to exit; memory is the median of the runs&#39; peak resident set (max RSS, from <code>wait4</code>). A ratio is native code&#39;s over Go&#39;s, so below 1.00× beats Go. A Go program starts at about 2 MB resident and a native Eyelang one at about 0.2 MB, so where a benchmark holds little data, its memory ratio shows that fixed cost rather than how values are stored.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Machine</td><td>Intel(R) Xeon(R) Processor @ 2.80GHz, 4 cores, linux/amd64</td></tr><tr><td>Go</td><td>go1.27.2</td></tr><tr><td>zig</td><td>0.17.0</td></tr><tr><td>Date</td><td>2026-10-12</td></tr><tr><td>Commit</td><td><code>a5ba1d0</code></td></tr></tbody></table><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benchmark</th><th style="text-align:right;">Native ms</th><th style="text-align:right;">Go ms</th><th style="text-align:right;">Time × Go</th><th style="text-align:right;">Native MB</th><th style="text-align:right;">Go MB</th><th style="text-align:right;">Memory × Go</th><th style="text-align:right;">Interpreter ms</th><th style="text-align:right;">Interpreter MB</th></tr></thead><tbody><tr><td>fib</td><td style="text-align:right;">233</td><td style="text-align:right;">138</td><td style="text-align:right;">1.69×</td><td style="text-align:right;">0.27</td><td style="text-align:right;">1.91</td><td style="text-align:right;">0.14×</td><td style="text-align:right;">9953</td><td style="text-align:right;">18.8</td></tr><tr><td>mandelbrot</td><td style="text-align:right;">249</td><td style="text-align:right;">217</td><td style="text-align:right;">1.15×</td><td style="text-align:right;">0.27</td><td style="text-align:right;">1.91</td><td style="text-align:right;">0.14×</td><td style="text-align:right;">29342</td><td style="text-align:right;">22.2</td></tr><tr><td>trees</td><td style="text-align:right;">316</td><td style="text-align:right;">482</td><td style="text-align:right;">0.66×</td><td style="text-align:right;">8.39</td><td style="text-align:right;">12.4</td><td style="text-align:right;">0.68×</td><td style="text-align:right;">10381</td><td style="text-align:right;">50.1</td></tr><tr><td>records</td><td style="text-align:right;">134</td><td style="text-align:right;">253</td><td style="text-align:right;">0.53×</td><td style="text-align:right;">0.28</td><td style="text-align:right;">2.03</td><td style="text-align:right;">0.14×</td><td style="text-align:right;">10455</td><td style="text-align:right;">21.1</td></tr><tr><td>strings</td><td style="text-align:right;">167</td><td style="text-align:right;">374</td><td style="text-align:right;">0.45×</td><td style="text-align:right;">67.9</td><td style="text-align:right;">48.1</td><td style="text-align:right;">1.41×</td><td style="text-align:right;">5894</td><td style="text-align:right;">930.2</td></tr><tr><td>lists</td><td style="text-align:right;">155</td><td style="text-align:right;">154</td><td style="text-align:right;">1.00×</td><td style="text-align:right;">19.5</td><td style="text-align:right;">48.1</td><td style="text-align:right;">0.41×</td><td style="text-align:right;">3542</td><td style="text-align:right;">134.1</td></tr><tr><td>maps</td><td style="text-align:right;">199</td><td style="text-align:right;">123</td><td style="text-align:right;">1.62×</td><td style="text-align:right;">0.90</td><td style="text-align:right;">2.53</td><td style="text-align:right;">0.36×</td><td style="text-align:right;">17388</td><td style="text-align:right;">22.4</td></tr><tr><td>logs</td><td style="text-align:right;">246</td><td style="text-align:right;">330</td><td style="text-align:right;">0.74×</td><td style="text-align:right;">43.8</td><td style="text-align:right;">59.8</td><td style="text-align:right;">0.73×</td><td style="text-align:right;">2194</td><td style="text-align:right;">79.4</td></tr><tr><td>lexer</td><td style="text-align:right;">561</td><td style="text-align:right;">870</td><td style="text-align:right;">0.65×</td><td style="text-align:right;">62.8</td><td style="text-align:right;">191.6</td><td style="text-align:right;">0.33×</td><td style="text-align:right;">30606</td><td style="text-align:right;">1620.8</td></tr></tbody></table><p>Faster than Go: trees, records, strings, logs, lexer.<br> Less memory than Go: fib, mandelbrot, trees, records, lists, maps, logs, lexer.<br> Geometric mean: 0.85× Go&#39;s time, 0.36× Go&#39;s memory.</p><p>Where each gap comes from, and the work that must close it, is in the <a href="./reviews/native-plan-2026-10-12#against-go">native compilation plan</a>.</p><h2 id="the-benchmarks" tabindex="-1">The benchmarks <a class="header-anchor" href="#the-benchmarks" aria-label="Permalink to &quot;The benchmarks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benchmark</th><th>What it exercises</th></tr></thead><tbody><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/fib" target="_blank" rel="noreferrer"><code>fib</code></a></td><td>calls and integers: naive fib(37)</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/mandelbrot" target="_blank" rel="noreferrer"><code>mandelbrot</code></a></td><td>floats: a 1600×1600 Mandelbrot set, 100 iterations</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/trees" target="_blank" rel="noreferrer"><code>trees</code></a></td><td>allocation: binary trees of depth 4 to 16</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/records" target="_blank" rel="noreferrer"><code>records</code></a></td><td>records: <code>with</code> updates of a 5-field record in a loop</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/strings" target="_blank" rel="noreferrer"><code>strings</code></a></td><td>strings: build a 1M-item string with <code>+=</code>, then split it</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/lists" target="_blank" rel="noreferrer"><code>lists</code></a></td><td>lists: map, filter and sum over 1M ints; sort 1M</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/maps" target="_blank" rel="noreferrer"><code>maps</code></a></td><td>maps: count 5M words over 5,000 keys</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/logs" target="_blank" rel="noreferrer"><code>logs</code></a></td><td>text: generate a 200k-line log, parse it, aggregate per service</td></tr><tr><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/lexer" target="_blank" rel="noreferrer"><code>lexer</code></a></td><td>a real program: Eyelang&#39;s lexer in Eyelang against syntax/lexer.go, on 7.5 MB of Eyelang</td></tr></tbody></table><h2 id="running-them" tabindex="-1">Running them <a class="header-anchor" href="#running-them" aria-label="Permalink to &quot;Running them&quot;">​</a></h2><p>From the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tools/bench</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # the table: 5 runs of each binary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tools/bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fib</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # one benchmark, or a comma-separated list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tools/bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-interp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # without the interpreter, which is the slow part</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tools/bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # fail when native code got worse against Go</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tools/bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --write</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # record new results: this page and testdata/bench/results.json</span></span></code></pre></div><p><code>--check</code> reruns the suite and compares each ratio with the one recorded in <code>testdata/bench/results.json</code>. It fails when native code&#39;s time against Go&#39;s grew by more than 25%, or its memory against Go&#39;s by more than 15% and by more than 1 MB. A benchmark that looks worse is measured up to 2 more times, keeping its best time and memory, so a slow stretch of the machine doesn&#39;t fail the check and a real regression still does. Ratios against Go on the same machine cancel most of the difference between machines, but not all of it, so record new results on the machine you check on. CI doesn&#39;t run the timing check, since shared runners are too noisy for it; <code>go test ./tools/bench</code> (skipped under <code>-short</code>) builds every benchmark and runs it at a small size, only to check that native code, Go and the interpreter print the same.</p><p>A new benchmark is a directory under <code>testdata/bench</code> with an Eyelang program whose <code>main</code> does the work and a <code>main.go</code> doing the same in Go, both taking the same arguments (usually an optional size), plus a line in <code>tools/bench</code>&#39;s suite with the arguments of a measured run and of a quick one. <code>main.go</code> is built from the repository root, inside its module, so it may import the repository&#39;s packages. Size a benchmark to run 100 ms to 1 s in Go.</p>`,15)])])}const p=e(r,[["render",n]]);export{y as __pageData,p as default};
